    if (tr === 'checker') { const cols = 8, rows = 14, cw = W / cols, ch = H / rows; for (let j = 0; j < rows; j++)for (let i = 0; i < cols; i++) { const k = clamp(1 - (q * 1.7 - ((i / cols + j / rows) * .35 + (((i + j) % 2) ? .35 : 0)))); if (k > 0) { const w = cw * k, h = ch * k; c.fillRect(i * cw + (cw - w) / 2 - .5, j * ch + (ch - h) / 2 - .5, w + 1, h + 1); } } }
